/* ================= KADANE ================= */
// 1
int maxSubArraySum(vector<int>& nums) {
    int maxi=INT_MIN , sum=0;
    for (int i = 0; i < nums.size(); i++)
    {
        sum+=nums[i];
        if(sum>maxi){
            maxi = sum;
        }
        if(sum<0){
            sum=0; // starting a new subarray
        }
    }
    return maxi;
}
// 2
ll kadane(const vector<ll>& a){
    ll cur = 0, mx = -INF;
    for(ll x : a){
        cur = max(x, cur + x);
        mx = max(mx, cur);
    }
    return mx;
}

