/* ================= TOPOLOGICAL SORT ================= */

vector<int> topo_sort(int n){
    vector<int> indeg(n,0), topo;
    for(int u = 0; u < n; u++)
        for(int v : adj[u])
            indeg[v]++;

    queue<int> q;
    for(int i = 0; i < n; i++)
        if(indeg[i] == 0) q.push(i);

    while(!q.empty()){
        int u = q.front(); q.pop();
        topo.push_back(u);
        for(int v : adj[u])
            if(--indeg[v] == 0)
                q.push(v);
    }
    return topo;
}

/* ================= DIJKSTRA ================= */

vector<pll> wadj[N];
ll dist[N];

void dijkstra(int src){
    priority_queue<pll, vector<pll>, greater<pll>> pq;
    fill(dist, dist + N, INF);
    dist[src] = 0;
    pq.push({0, src});

    while(!pq.empty()){
        auto [d, u] = pq.top(); pq.pop();
        if(d > dist[u]) continue;
        for(auto [v, w] : wadj[u]){
            if(dist[v] > d + w){
                dist[v] = d + w;
                pq.push({dist[v], v});
            }
        }
    }
}


/* ================= DSU (UNION FIND) ================= */

int parent[N], sz_dsu[N];



void make_set(int n){
    for(int i = 0; i < n; i++){
        parent[i] = i;
        sz_dsu[i] = 1;
    }
}

int find_set(int v){
    if(v == parent[v]) return v;
    return parent[v] = find_set(parent[v]);
}

void union_sets(int a, int b){
    a = find_set(a);
    b = find_set(b);
    if(a != b){
        if(sz_dsu[a] < sz_dsu[b]) swap(a, b);
        parent[b] = a;
        sz_dsu[a] += sz_dsu[b];
    }
}

