// ===== Next Greater Element (NGE) =====
vector<int> nge(n, -1);
stack<int> st;
for(int i = 0; i < n; i++){
    while(!st.empty() && a[st.top()] < a[i]){
        nge[st.top()] = a[i];
        st.pop();
    }
    st.push(i);
}

// ===== Next Smaller Element (NSE) =====
vector<int> nse(n, -1);
while(!st.empty()) st.pop();
for(int i = 0; i < n; i++){
    while(!st.empty() && a[st.top()] > a[i]){
        nse[st.top()] = a[i];
        st.pop();
    }
    st.push(i);
}

// ===== Previous Greater Element (PGE) =====
vector<int> pge(n, -1);
while(!st.empty()) st.pop();
for(int i = 0; i < n; i++){
    while(!st.empty() && a[st.top()] <= a[i]) st.pop();
    if(!st.empty()) pge[i] = a[st.top()];
    st.push(i);
}

// ===== Previous Smaller Element (PSE) =====
vector<int> pse(n, -1);
while(!st.empty()) st.pop();
for(int i = 0; i < n; i++){
    while(!st.empty() && a[st.top()] >= a[i]) st.pop();
    if(!st.empty()) pse[i] = a[st.top()];
    st.push(i);
}










/* ================= TREE TRAVERSALS ================= */

// ===== Depth First Search (DFS) =====

// Preorder   (Root → Left → Right)
void preorder(TreeNode* root){
    if(!root) return;
    // visit(root)
    preorder(root->left); // in
    preorder(root->right); // post
}





// ===== Breadth First Search (BFS) =====
// Level Order Traversal
void levelOrder(TreeNode* root){
    if(!root) return;
    queue<TreeNode*> q;
    q.push(root);
    while(!q.empty()){
        TreeNode* cur = q.front(); q.pop();
        // visit(cur)
        if(cur->left) q.push(cur->left);
        if(cur->right) q.push(cur->right);
    }
}


/* ================= COMBINATORICS =================
   Supports:
   - nCr (Combination)
   - nPr (Permutation)
   - Factorials
   - Modular inverse
   - O(1) query after O(N) precompute
   NOTE: MOD must be prime (e.g. 1e9+7)
================================================= */

const int MAXF = 1e6 + 5;   // adjust based on constraints
ll fact[MAXF], invfact[MAXF];

// Fast exponentiation
ll binpow(ll a, ll b, ll mod = MOD){
    ll res = 1;
    while(b){
        if(b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

// Precompute factorials and inverse factorials
void init_combinatorics(){
    fact[0] = 1;
    for(int i = 1; i < MAXF; i++)
        fact[i] = fact[i-1] * i % MOD;

    // Fermat inverse of fact[n]
    invfact[MAXF-1] = binpow(fact[MAXF-1], MOD - 2);

    for(int i = MAXF - 2; i >= 0; i--)
        invfact[i] = invfact[i+1] * (i+1) % MOD;
}

// nCr = n! / (r! * (n-r)!)
ll nCr(int n, int r){
    if(r < 0 || r > n) return 0;
    return fact[n] * invfact[r] % MOD * invfact[n - r] % MOD;
}

// nPr = n! / (n-r)!
ll nPr(int n, int r){
    if(r < 0 || r > n) return 0;
    return fact[n] * invfact[n - r] % MOD;
}

